{"explanation":"A Riemann sum approximates area by adding the areas of rectangles. Here, each rectangle has width 2/n and a height taken from y = x² at its midpoint. Move the slider to increase the number of rectangles: the sum approaches the exact area, ∫₀² x² dx = 8/3 ≈ 2.66667.","manimCode":"const heading = new Text({ text: 'Riemann sums: area under y = x²', fontSize: 30, color: WHITE });
heading.moveTo([0, 3.15, 0]);
const axes = new Axes({
  xRange: [-0.15, 2.3, 0.5],
  yRange: [-0.3, 4.7, 1],
  xLength: 8,
  yLength: 4.2,
  tips: false
});
axes.moveTo([-1.1, -0.15, 0]);
const curve = axes.plot(x => x * x, { xRange: [0, 2], color: YELLOW, numSamples: 160 });
const axisNumbers = new VGroup();
for (const val of [0, 1, 2]) {
  const tickLabel = new Text({ text: String(val), fontSize: 19, color: GRAY });
  tickLabel.moveTo(axes.c2p(val, 0));
  tickLabel.shift([0, -0.25, 0]);
  axisNumbers.add(tickLabel);
}
for (const val of [2, 4]) {
  const tickLabel = new Text({ text: String(val), fontSize: 19, color: GRAY });
  tickLabel.moveTo(axes.c2p(0, val));
  tickLabel.shift([-0.28, 0, 0]);
  axisNumbers.add(tickLabel);
}
const formula = new MathTex({ latex: '\\Delta x=\\frac{2}{n},\\qquad S_n=\\sum_{i=0}^{n-1}\\left((i+\\tfrac12)\\Delta x\\right)^2\\Delta x' });
await formula.waitForRender();
formula.scale(0.7);
formula.moveTo([0, -3.15, 0]);
await scene.play(new AnimationGroup([new Write(heading), new Create(axes)]));
scene.add(axisNumbers, formula);
let bars = null;
let readout = null;
function updateRectangles(count) {
  const n = Math.max(1, Math.round(count));
  const dx = 2 / n;
  if (bars) scene.remove(bars);
  if (readout) scene.remove(readout);
  bars = new VGroup();
  let total = 0;
  for (let i = 0; i < n; i++) {
    const left = i * dx;
    const right = (i + 1) * dx;
    const mid = (left + right) / 2;
    const height = mid * mid;
    total += height * dx;
    const rect = new Polygon({
      vertices: [axes.c2p(left, 0), axes.c2p(right, 0), axes.c2p(right, height), axes.c2p(left, height)],
      color: BLUE
    });
    rect.setFill(BLUE, 0.4);
    rect.setStrokeWidth(n > 40 ? 0.7 : 1.3);
    bars.add(rect);
  }
  scene.add(bars);
  scene.remove(curve);
  scene.add(curve);
  readout = new Text({
    text: 'n = ' + n + '     Midpoint sum = ' + total.toFixed(5) + '     Exact area = 2.66667',
    fontSize: 23,
    color: WHITE
  });
  readout.moveTo([0, -2.55, 0]);
  scene.add(readout);
}
updateRectangles(8);
const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 250 });
controls.addSlider({ label: 'Number of rectangles', min: 1, max: 80, step: 1, value: 8, onChange: updateRectangles });
await scene.wait(999999);"}

